import { seeded, secure, type Rng } from '../../../packages/engine/src/rng';
import type { GameEvent } from '../../../packages/shared/src/index';
export function uniqueId() { if (crypto.randomUUID)
    return crypto.randomUUID(); const bytes = new Uint8Array(16); crypto.getRandomValues(bytes); return Array.from(bytes, n => n.toString(16).padStart(2, '0')).join(''); }
/** Recover generator position from actual draws, not replayed/reused draws. No random value is generated by undo. */
export function restoreRng(seed: string | null, events: GameEvent[]): {
    dice: Rng;
    agents: Rng;
} {
    if (!seed)
        return { dice: secure, agents: secure };
    const dice = seeded(seed + ':dice'), agents = seeded(seed + ':agents');
    let rollSeq = -1;
    const agentRolls = new Set<number>();
    for (const e of events) {
        if (e.type === 'initial_roll')
            for (const _ of Object.keys((e.payload as {
                values: Record<string, number>;
            }).values))
                dice.die();
        if (e.type === 'dice_roll') {
            rollSeq = e.seq;
            if ((e.payload as {
                reusedFrom?: number;
            }).reusedFrom === undefined) {
                dice.die();
                dice.die();
            }
        }
        if (e.decisionMaker?.kind === 'agent' && ['random', 'greedy', 'tactical'].includes(e.decisionMaker.id))
            agentRolls.add(rollSeq);
    }
    for (const _ of agentRolls)
        agents.next();
    return { dice, agents };
}
